const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const ui={overlay:document.getElementById('overlay'),start:document.getElementById('startBtn'),round:document.getElementById('round'),health:document.getElementById('healthNum'),healthFill:document.getElementById('healthFill'),cash:document.getElementById('cash'),ammo:document.getElementById('ammo'),weapon:document.getElementById('weaponName'),ammoLabel:document.getElementById('ammoLabel'),hint:document.getElementById('hint'),toast:document.getElementById('toast'),mobile:document.getElementById('mobile')};
let W=innerWidth,H=innerHeight,DPR=1;function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
const world={w:1900,h:1320};
const obstacles=[
 {x:265,y:220,w:230,h:115,t:'truck'},{x:1440,y:205,w:230,h:135,t:'crate'},
 {x:260,y:990,w:220,h:125,t:'crate'},{x:1430,y:990,w:245,h:130,t:'truck'},
 {x:715,y:175,w:95,h:100,t:'box'},{x:1085,y:1040,w:120,h:95,t:'box'},
 {x:720,y:1000,w:140,h:85,t:'barrel'},{x:1090,y:205,w:135,h:90,t:'barrel'},
 {x:90,y:480,w:110,h:210,t:'wall'},{x:1700,y:470,w:105,h:220,t:'wall'},
 {x:815,y:565,w:100,h:180,t:'box'},{x:1000,y:600,w:115,h:155,t:'box'}
];
const weapons=[{name:'M-9 SERVICE',label:'SIDEARM / SEMI',mag:12,reserve:60,damage:44,rate:250,reload:1.05,spread:.035,price:0,auto:false},{name:'RANGER SMG',label:'SUBMACHINE / AUTO',mag:32,reserve:160,damage:27,rate:105,reload:1.45,spread:.09,price:700,auto:true},{name:'BREACH-12',label:'COMBAT SHOTGUN',mag:8,reserve:48,damage:26,rate:650,reload:1.8,spread:.32,pellets:7,price:1100,auto:false},{name:'VANGUARD AR',label:'ASSAULT / AUTO',mag:30,reserve:150,damage:38,rate:135,reload:1.55,spread:.065,price:1800,auto:true}];
let player,zombies=[],bullets=[],particles=[],pickups=[],round=1,kills=0,score=0,gameStarted=false,gameOver=false,spawnLeft=0,spawnTimer=0,roundPause=0,elapsed=0,fireHeld=false,aimPointer=null,keys={},lastTime=0,toastTimer=0,hintTimer=0,grenades=3,grenadeCooldown=0,screenShake=0;
function fresh(){player={x:950,y:660,r:18,angle:-Math.PI/2,hp:100,maxHp:100,points:500,weapon:0,ammo:12,reserve:60,reloading:0,lastShot:0,invuln:0};zombies=[];bullets=[];particles=[];pickups=[];round=1;kills=0;score=0;spawnLeft=0;spawnTimer=0;roundPause=1.5;grenades=3;gameOver=false;gameStarted=true;nextRound();updateHUD()}
function nextRound(){spawnLeft=5+round*4;spawnTimer=.45;toast('WAVE '+String(round).padStart(2,'0')+' INCOMING');}
function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.65}
function updateHUD(){if(!player)return;ui.round.textContent=String(round).padStart(2,'0');ui.health.textContent=Math.max(0,Math.ceil(player.hp));ui.healthFill.style.width=(player.hp/player.maxHp*100)+'%';ui.healthFill.style.background=player.hp<35?'#ff594d':'var(--acid)';ui.cash.textContent='◈ '+player.points;const w=weapons[player.weapon];ui.weapon.textContent=w.name;ui.ammoLabel.textContent=w.label;ui.ammo.innerHTML=(player.reloading>0?'RELOADING':player.ammo)+' <span>/ '+player.reserve+'</span>';}
function startGame(){ui.overlay.classList.add('hidden');ui.mobile.style.display='block';fresh();lastTime=performance.now()}
ui.start.addEventListener('click',startGame);
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function rand(a,b){return a+Math.random()*(b-a)}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function circleRect(x,y,r,o){let nx=clamp(x,o.x,o.x+o.w),ny=clamp(y,o.y,o.y+o.h),dx=x-nx,dy=y-ny;return dx*dx+dy*dy<r*r}
function collides(x,y,r){if(x<r+35||y<r+35||x>world.w-r-35||y>world.h-r-35)return true;return obstacles.some(o=>circleRect(x,y,r,o))}
function moveEntity(e,dx,dy){if(!collides(e.x+dx,e.y,e.r))e.x+=dx;if(!collides(e.x,e.y+dy,e.r))e.y+=dy}
function spawnZombie(){const a=Math.random()*Math.PI*2,d=Math.max(W,H)*.65+120;let x=clamp(player.x+Math.cos(a)*d,45,world.w-45),y=clamp(player.y+Math.sin(a)*d,45,world.h-45);for(let n=0;n<obstacles.length&&collides(x,y,18);n++){x=rand(50,world.w-50);y=rand(50,world.h-50)}let kind=round>4&&Math.random()<.18?'runner':'shambler';zombies.push({x,y,r:kind==='runner'?14:17,hp:(kind==='runner'?62:92)+round*13,maxHp:92+round*13,speed:(kind==='runner'?74:39)+Math.min(round*2,22),kind,attack:0,hit:0,angle:0});}
function shoot(){if(!gameStarted||gameOver||player.reloading>0)return;const w=weapons[player.weapon],now=elapsed*1000;if(now-player.lastShot<w.rate)return;if(player.ammo<=0){toast('MAGAZINE EMPTY — RELOAD');player.lastShot=now;return}player.lastShot=now;player.ammo--;let n=w.pellets||1;for(let i=0;i<n;i++){let a=player.angle+rand(-w.spread,w.spread);bullets.push({x:player.x+Math.cos(a)*24,y:player.y+Math.sin(a)*24,vx:Math.cos(a)*720,vy:Math.sin(a)*720,life:.42,damage:w.damage*(w.pellets?rand(.75,1.15):1),r:w.pellets?3:2.5});}particles.push({x:player.x+Math.cos(player.angle)*25,y:player.y+Math.sin(player.angle)*25,life:.09,max:.09,color:'#e6ff99',r:10});screenShake=Math.max(screenShake,w.pellets?.055:.025);if(player.ammo===0)toast('MAGAZINE EMPTY');updateHUD()}
function reload(){if(!player||player.reloading||player.ammo>=weapons[player.weapon].mag||player.reserve<=0)return;player.reloading=weapons[player.weapon].reload;toast('RELOADING');updateHUD()}
function buy(){if(!gameStarted||gameOver)return;let best=null,bd=1e9;for(const o of obstacles){let d=Math.hypot(player.x-(o.x+o.w/2),player.y-(o.y+o.h/2));if(d<bd){bd=d;best=o}}if(bd<155){if(player.weapon<weapons.length-1){let next=weapons[player.weapon+1];if(player.points>=next.price){player.points-=next.price;player.weapon++;player.ammo=next.mag;player.reserve=next.reserve;toast('ACQUIRED: '+next.name);updateHUD()}else toast('NEED ◈ '+next.price)}else if(player.points>=250){player.points-=250;player.hp=Math.min(100,player.hp+35);toast('FIELD DRESSING +35');updateHUD()}else toast('NEED ◈ 250')}else if(bd<250)toast('OUT OF RANGE');else toast('FIND A SUPPLY CACHE')}
function frag(){if(!gameStarted||gameOver||grenades<=0||grenadeCooldown>0)return;grenades--;grenadeCooldown=1;let a=player.angle;let g={x:player.x+Math.cos(a)*100,y:player.y+Math.sin(a)*100,life:.48};particles.push({x:g.x,y:g.y,life:.48,max:.48,color:'#e2d59a',r:4,grenade:true});setTimeout(()=>{if(!gameStarted)return;for(let z of zombies){let d=Math.hypot(z.x-g.x,z.y-g.y);if(d<240){z.hp-=Math.round(400*(1-d/300));z.hit=.18}}for(let i=0;i<32;i++){let an=Math.random()*Math.PI*2,sp=rand(70,360);particles.push({x:g.x,y:g.y,vx:Math.cos(an)*sp,vy:Math.sin(an)*sp,life:rand(.25,.65),max:.65,color:Math.random()<.5?'#ffb84f':'#e8e1ae',r:rand(2,7)})}screenShake=.22;toast('FRAG OUT');},480);}

function update(dt){elapsed+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}if(hintTimer>0){hintTimer-=dt;if(hintTimer<=0)ui.hint.classList.remove('show')}if(!gameStarted)return;if(gameOver)return;
 let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joy.x,dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+joy.y;let len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}moveEntity(player,dx*220*dt,dy*220*dt);
 if(aimPointer&&aimPointer.active){let wx=aimPointer.x,wy=aimPointer.y;player.angle=Math.atan2(wy-player.y,wx-player.x)}else if(zombies.length){let nearest=zombies.reduce((a,b)=>dist(a,player)<dist(b,player)?a:b);if(dist(nearest,player)<240)player.angle=Math.atan2(nearest.y-player.y,nearest.x-player.x)}
 if(fireHeld||keys.Space)shoot();if(player.reloading>0){player.reloading-=dt;if(player.reloading<=0){let w=weapons[player.weapon],take=Math.min(w.mag-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;player.reloading=0;updateHUD()}}if(player.invuln>0)player.invuln-=dt;if(grenadeCooldown>0)grenadeCooldown-=dt;if(screenShake>0)screenShake=Math.max(0,screenShake-dt);
 if(spawnLeft>0){spawnTimer-=dt;if(spawnTimer<=0){spawnZombie();spawnLeft--;spawnTimer=Math.max(.38,1.05-round*.035)}}else if(zombies.length===0){roundPause-=dt;if(roundPause<=0){round++;player.points+=100;player.hp=Math.min(100,player.hp+8);player.reserve+=Math.ceil(weapons[player.weapon].mag*.35);roundPause=2.2;nextRound();updateHUD()}}
 for(let z of zombies){let dxp=player.x-z.x,dyp=player.y-z.y,d=Math.hypot(dxp,dyp)||1;z.angle=Math.atan2(dyp,dxp);z.hit=Math.max(0,z.hit-dt);if(d>z.r+player.r+3){let step=z.speed*dt;moveEntity(z,dxp/d*step,dyp/d*step)}else{z.attack-=dt;if(z.attack<=0&&player.invuln<=0){player.hp-=z.kind==='runner'?14:10;player.invuln=.48;z.attack=.9;screenShake=.13;updateHUD();if(player.hp<=0){player.hp=0;gameOver=true;setTimeout(showGameOver,650)}}}}
 for(let b of bullets){let ox=b.x;b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(let z of zombies){if(z.hp>0&&Math.hypot(z.x-b.x,z.y-b.y)<z.r+b.r){z.hp-=b.damage;z.hit=.12;b.life=0;if(z.hp<=0){player.points+=60;kills++;score+=100;particles.push({x:z.x,y:z.y,life:.45,max:.45,color:'#7b2520',r:15});if(Math.random()<.055)pickups.push({x:z.x,y:z.y,type:Math.random()<.55?'ammo':'med',life:12})}break}}}bullets=bullets.filter(b=>b.life>0);zombies=zombies.filter(z=>z.hp>0);
 for(let p of particles){p.life-=dt;if(p.vx){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96}}particles=particles.filter(p=>p.life>0);
 for(let p of pickups){p.life-=dt;if(dist(player,p)<30){if(p.type==='med'){player.hp=Math.min(100,player.hp+28);toast('MEDKIT +28')}else{player.reserve+=Math.ceil(weapons[player.weapon].mag*1.6);toast('AMMO RESUPPLIED')}p.life=0;updateHUD()}}pickups=pickups.filter(p=>p.life>0);
 updateHUD();}
function showGameOver(){if(!gameOver)return;ui.mobile.style.display='none';ui.overlay.classList.remove('hidden');document.querySelector('.eyebrow').textContent='MISSION TERMINATED';document.querySelector('.title').innerHTML='NIGHT<br><span>CLAIMED</span>';document.querySelector('.subtitle').textContent=`You survived ${Math.max(1,round)} waves and eliminated ${kills} infected. Final score: ${score.toLocaleString()}. The outpost is lost — redeploy when ready.`;ui.start.innerHTML='REDEPLOY &nbsp;↻';}
const joy={x:0,y:0};let stickPointer=null,stickOrigin={x:0,y:0};const stick=document.getElementById('stick'),knob=document.getElementById('knob');
function setJoy(e){let r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,d=Math.hypot(dx,dy);if(d>max){dx*=max/d;dy*=max/d}joy.x=dx/max;joy.y=dy/max;knob.style.left=`calc(50% + ${dx}px)`;knob.style.top=`calc(50% + ${dy}px)`}
stick.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);setJoy(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)setJoy(e)});function endStick(e){if(e.pointerId===stickPointer){stickPointer=null;joy.x=joy.y=0;knob.style.left='50%';knob.style.top='50%'}}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
let aimTouch=null;canvas.addEventListener('pointerdown',e=>{if(!gameStarted||gameOver)return;if(e.pointerType==='mouse'){const p=screenToWorld(e.clientX,e.clientY);aimPointer={...p,active:true};fireHeld=true;canvas.setPointerCapture(e.pointerId)}else if(e.clientX>W*.42){aimTouch=e.pointerId;const p=screenToWorld(e.clientX,e.clientY);aimPointer={...p,active:true};fireHeld=true;canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'&&gameStarted){let p=screenToWorld(e.clientX,e.clientY);aimPointer={...p,active:true}}else if(e.pointerId===aimTouch){let p=screenToWorld(e.clientX,e.clientY);aimPointer={...p,active:true}}});function endAim(e){if(e.pointerType==='mouse'){fireHeld=false}else if(e.pointerId===aimTouch){aimTouch=null;fireHeld=false}}canvas.addEventListener('pointerup',endAim);canvas.addEventListener('pointercancel',endAim);
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reload();if(e.code==='KeyG')frag();if(e.code==='KeyF')buy();if(e.code==='KeyE')buy()});addEventListener('keyup',e=>keys[e.code]=false);
document.getElementById('fireBtn').addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true});document.getElementById('fireBtn').addEventListener('pointerup',()=>fireHeld=false);document.getElementById('fireBtn').addEventListener('pointercancel',()=>fireHeld=false);document.getElementById('reloadBtn').addEventListener('click',reload);document.getElementById('grenadeBtn').addEventListener('click',frag);document.getElementById('buyBtn').addEventListener('click',buy);
function camera(){let zoom=Math.max(.38,Math.min(1.05,Math.min(W/1000,H/700)));let px=player?player.x:950,py=player?player.y:660;return{zoom,x:W/2-px*zoom,y:H/2-py*zoom}}
function screenToWorld(sx,sy){let c=camera();return{x:(sx-c.x)/c.zoom,y:(sy-c.y)/c.zoom}}

function draw(){ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);const c=camera(),sh=screenShake?rand(-screenShake,screenShake)*24:0;ctx.save();ctx.translate(c.x+sh,c.y+sh);ctx.scale(c.zoom,c.zoom);drawWorld();ctx.restore();}
function drawWorld(){let t=elapsed;
// concrete yard
ctx.fillStyle='#29312c';ctx.fillRect(0,0,world.w,world.h);ctx.fillStyle='#343b35';ctx.fillRect(40,40,world.w-80,world.h-80);
// worn floor sections
for(let y=70;y<world.h-60;y+=150)for(let x=70;x<world.w-60;x+=180){ctx.fillStyle=((x/180+y/150)%2>1)?'#343b35':'#323a34';ctx.fillRect(x,y,176,146);ctx.strokeStyle='#59605422';ctx.lineWidth=2;ctx.strokeRect(x+1,y+1,174,144)}
// service lane and markings
ctx.fillStyle='#252d29';ctx.fillRect(0,535,world.w,246);ctx.fillStyle='#b9ac6a';ctx.globalAlpha=.5;for(let x=40;x<world.w;x+=120){ctx.fillRect(x,544,58,4);ctx.fillRect(x,768,58,4)}ctx.globalAlpha=1;
// crack and stains
for(let i=0;i<35;i++){let x=(i*317+71)%world.w,y=(i*193+103)%world.h;ctx.strokeStyle=i%3?'#131a1680':'#b8ab7623';ctx.lineWidth=i%3?2:5;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+12+(i%6)*5,y+7+(i%4)*4);ctx.lineTo(x+22+(i%6)*7,y+1+(i%4)*8);ctx.stroke()}
// perimeter wall/fence
ctx.fillStyle='#161d19';ctx.fillRect(0,0,world.w,38);ctx.fillRect(0,world.h-38,world.w,38);ctx.fillRect(0,0,38,world.h);ctx.fillRect(world.w-38,0,38,world.h);
ctx.strokeStyle='#9ca79766';ctx.lineWidth=3;ctx.strokeRect(38,38,world.w-76,world.h-76);ctx.lineWidth=1;for(let x=55;x<world.w-50;x+=30){ctx.beginPath();ctx.moveTo(x,38);ctx.lineTo(x,66);ctx.moveTo(x,world.h-38);ctx.lineTo(x,world.h-66);ctx.stroke()}for(let y=58;y<world.h-50;y+=30){ctx.beginPath();ctx.moveTo(38,y);ctx.lineTo(66,y);ctx.moveTo(world.w-38,y);ctx.lineTo(world.w-66,y);ctx.stroke()}
// pool of light
for(const light of [{x:540,y:410},{x:1370,y:870},{x:930,y:180},{x:940,y:1120}]){let g=ctx.createRadialGradient(light.x,light.y,5,light.x,light.y,270);g.addColorStop(0,'#e3ce8130');g.addColorStop(1,'#e3ce8100');ctx.fillStyle=g;ctx.fillRect(light.x-270,light.y-270,540,540);ctx.fillStyle='#e2d38c';ctx.beginPath();ctx.arc(light.x,light.y,4,0,Math.PI*2);ctx.fill()}
for(const o of obstacles)drawObstacle(o);
for(const p of pickups){let bob=Math.sin(elapsed*5+p.x)*4;ctx.save();ctx.translate(p.x,p.y+bob);ctx.shadowBlur=22;ctx.shadowColor=p.type==='med'?'#d5ff3f':'#65d8ff';ctx.fillStyle=p.type==='med'?'#d5ff3f':'#71d8ed';ctx.fillRect(-10,-10,20,20);ctx.shadowBlur=0;ctx.fillStyle='#18211a';if(p.type==='med'){ctx.fillRect(-2,-7,4,14);ctx.fillRect(-7,-2,14,4)}else{ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText('A',0,5)}ctx.restore()}
for(const p of particles){let k=Math.max(0,p.life/p.max);ctx.globalAlpha=k;ctx.fillStyle=p.color;if(p.grenade){ctx.beginPath();ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fill()}else{ctx.beginPath();ctx.arc(p.x,p.y,p.r*k,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
for(const b of bullets){ctx.strokeStyle='#efffa9';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(b.x-b.vx*.025,b.y-b.vy*.025);ctx.lineTo(b.x,b.y);ctx.stroke()}
for(const z of zombies)drawZombie(z);
if(player)drawPlayer(player);
// subtle fog in corners
let fog=ctx.createRadialGradient(950,660,300,950,660,1100);fog.addColorStop(0,'#0c120d00');fog.addColorStop(1,'#070d0b88');ctx.fillStyle=fog;ctx.fillRect(0,0,world.w,world.h);
}
function drawObstacle(o){ctx.save();ctx.fillStyle='#0c100e88';ctx.fillRect(o.x+9,o.y+12,o.w,o.h);let grad=ctx.createLinearGradient(o.x,o.y,o.x,o.y+o.h);grad.addColorStop(0,'#687064');grad.addColorStop(.14,o.t==='truck'?'#59645e':'#575d52');grad.addColorStop(1,'#303832');ctx.fillStyle=grad;ctx.fillRect(o.x,o.y,o.w,o.h);ctx.strokeStyle='#91988977';ctx.lineWidth=3;ctx.strokeRect(o.x+2,o.y+2,o.w-4,o.h-4);
if(o.t==='truck'){ctx.fillStyle='#222a26';ctx.fillRect(o.x+12,o.y+14,o.w*.37,o.h-28);ctx.fillStyle='#91a69b44';ctx.fillRect(o.x+18,o.y+20,o.w*.28,o.h-40);ctx.fillStyle='#202521';ctx.fillRect(o.x+o.w*.72,o.y+8,o.w*.18,o.h-16);ctx.fillStyle='#b9ac6877';ctx.fillRect(o.x+o.w*.54,o.y+10,5,o.h-20)}else if(o.t==='barrel'){ctx.fillStyle='#8c4737';ctx.fillRect(o.x+o.w*.2,o.y+8,o.w*.6,o.h-16);ctx.fillStyle='#b08755';ctx.fillRect(o.x+o.w*.2,o.y+20,o.w*.6,5);ctx.fillRect(o.x+o.w*.2,o.y+o.h-26,o.w*.6,5)}else{ctx.strokeStyle='#292f2a';ctx.lineWidth=4;for(let x=o.x+15;x<o.x+o.w;x+=32){ctx.beginPath();ctx.moveTo(x,o.y+8);ctx.lineTo(x,o.y+o.h-8);ctx.stroke()}ctx.strokeStyle='#87908166';ctx.lineWidth=2;ctx.strokeRect(o.x+10,o.y+10,o.w-20,o.h-20)}ctx.restore()}
function drawZombie(z){ctx.save();ctx.translate(z.x,z.y);ctx.rotate(z.angle);ctx.globalAlpha=z.hit>0?.68:1;ctx.fillStyle='#0a0d0b88';ctx.beginPath();ctx.ellipse(0,6,z.r+7,z.r*.8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=z.kind==='runner'?'#786c52':'#536455';ctx.beginPath();ctx.ellipse(0,0,z.r*.82,z.r*1.03,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#82836a';ctx.beginPath();ctx.arc(z.r*.45,-2,z.r*.52,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252c24';ctx.fillRect(z.r*.1,-z.r*.8,z.r*.48,4);ctx.fillRect(z.r*.1,z.r*.48,z.r*.55,4);ctx.fillStyle='#dc604a';ctx.fillRect(z.r*.66,-5,4,3);ctx.fillRect(z.r*.66,2,4,3);ctx.strokeStyle='#a5a07a';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(z.r*.2,-6);ctx.lineTo(z.r+10,-12);ctx.moveTo(z.r*.2,6);ctx.lineTo(z.r+9,13);ctx.stroke();ctx.restore()}

